theme.css:
/* ==== INTERFACE ====
   token  --bg #F4F6F9            页面底色｜冷调科研灰白底
   token  --text #141B25          正文主色｜冷墨石墨黑，高对比度
   token  --muted #596B82         次级成句与刻度线｜Slate冷灰，对比度>4.5:1
   token  --surface #FFFFFF       面板底色｜纯白卡片背景
   token  --panel-border #CDD6E2  结构描边｜冷灰边框线
   token  --primary #1B4982       主模型色｜分类器核心状态、主按钮、聚合决策
   token  --focus #0F3563         键盘焦点与激活轮廓｜深海军蓝
   token  --cls-pos #1E5AA8       正类(+1)语义｜正样本点、正类决策区
   token  --cls-neg #C8521A       负类(-1)语义｜负样本点、负类决策区
   token  --accent #C92A2A        关注焦点｜分类错误样本、加权惩罚、警戒
   token  --fs-h1 34px            页主标题
   token  --fs-h2 22px            区块主标题
   token  --fs-lead 19px          导语与提问
   token  --fs-body 18px          正文叙述
   token  --fs-sec 16px           次级说明与批注
   token  --fs-label 15px         控件与图例标签
   token  --fs-tick 13px          坐标刻度与纯数字
   版心   1488×844                #stage 宽1600高900已含 padding
   版式   .deck-split             左右等比或非对称主副分析区
   版式   .deck-stack             上下流程区与对照区
   组件   .panel                  带填色与描边的测量实验区
   组件   .panel.q                纯线框等边距问题区
   组件   .btn, .btns             标准交互按钮组
   组件   .ctl                    范围滑块与参数调控组件
   组件   .tag                    状态/类型标签
   组件   .legend                 图表图例容器
   组件   .quiz, .opt, .fb        课堂即问即答组件
   组件   .big, .num, .unit       数值突出读数
   ==== /INTERFACE ==== */

:root {
  --bg: #F4F6F9;
  --text: #141B25;
  --muted: #596B82;
  --surface: #FFFFFF;
  --panel-border: #CDD6E2;
  --primary: #1B4982;
  --focus: #0F3563;
  --cls-pos: #1E5AA8;
  --cls-neg: #C8521A;
  --accent: #C92A2A;

  --font-sans: "SF Pro Text", "Segoe UI", -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  --font-mono: "SF Mono", "Cascadia Code", Consolas, "JetBrains Mono", monospace;

  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --pad-x: 56px;
  --pad-y: 28px;
}

#stage {
  display: flex;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.45;
  box-sizing: border-box;
  user-select: none;
  overflow: hidden;
}

/* 典型区域布局 */
.deck-split {
  display: flex;
  gap: 28px;
  flex: 1;
  min-height: 0;
}

.deck-split > .col-main {
  flex: 1.3;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.deck-split > .col-side {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.deck-stack {
  display: flex;
  flex-direction: column;
  gap: 20px;
  flex: 1;
  min-height: 0;
}

/* 标题与文字阶层 */
h1.page-title {
  margin: 0 0 16px 0;
  font-size: var(--fs-h1);
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--text);
  display: flex;
  align-items: baseline;
  gap: 16px;
}

h1.page-title .step-badge {
  font-size: var(--fs-sec);
  font-family: var(--font-mono);
  font-weight: 600;
  color: var(--primary);
  background: #E8EEF5;
  padding: 2px 10px;
  border-radius: 4px;
}

h2.block-title {
  margin: 0 0 12px 0;
  font-size: var(--fs-h2);
  font-weight: 600;
  color: var(--text);
}

.lead {
  font-size: var(--fs-lead);
  line-height: 1.5;
  color: var(--text);
  margin: 0 0 16px 0;
}

.small, .note {
  font-size: var(--fs-sec);
  line-height: 1.4;
  color: var(--muted);
  margin: 0;
}

/* 面板容器 */
.panel {
  background: var(--surface);
  border: 1px solid var(--panel-border);
  border-radius: 8px;
  padding: 20px 24px;
  box-sizing: border-box;
}

.panel.q {
  background: transparent;
  border: 1px dashed var(--muted);
}

/* 数值与刻度 */
.big {
  font-family: var(--font-mono);
  font-size: 38px;
  font-weight: 700;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  color: var(--text);
}

.big.sm {
  font-size: 26px;
}

.big.lg {
  font-size: 52px;
}

.num {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.unit {
  font-size: var(--fs-sec);
  font-weight: 400;
  color: var(--muted);
  margin-left: 4px;
}

/* 标记与标签 */
.tag {
  display: inline-flex;
  align-items: center;
  font-size: var(--fs-label);
  padding: 3px 8px;
  border-radius: 4px;
  font-weight: 600;
  background: #E8EDF2;
  color: var(--text);
}

.tag.pos {
  background: #E3ECF7;
  color: var(--cls-pos);
}

.tag.neg {
  background: #FCEEE6;
  color: var(--cls-neg);
}

.tag.accent {
  background: #FDEDEB;
  color: var(--accent);
}

/* 图例系统 */
.legend {
  display: flex;
  align-items: center;
  gap: 18px;
  font-size: var(--fs-label);
  color: var(--muted);
}

.legend .li {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.legend .sw {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  flex-shrink: 0;
}

.legend .sw.square {
  border-radius: 2px;
}

.legend .sw.line {
  width: 18px;
  height: 2px;
  border-radius: 0;
}

.sw.pos { background-color: var(--cls-pos); }
.sw.neg { background-color: var(--cls-neg); }
.sw.accent { background-color: var(--accent); }
.sw.model { background-color: var(--primary); }

/* 操作与控制 */
.ctl {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ctl label {
  font-size: var(--fs-label);
  font-weight: 600;
  color: var(--text);
  display: flex;
  justify-content: space-between;
}

.ctl input[type="range"] {
  width: 100%;
  accent-color: var(--primary);
  height: 6px;
  background: var(--panel-border);
  border-radius: 3px;
  outline: none;
}

.ctl input[type="range"]:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  font-weight: 600;
  padding: 8px 18px;
  border-radius: 6px;
  border: 1px solid var(--primary);
  background: var(--primary);
  color: #FFFFFF;
  cursor: pointer;
  transition: opacity 0.15s ease, background-color 0.15s ease;
}

.btn:hover:not(:disabled) {
  opacity: 0.92;
}

.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn:disabled {
  border-color: var(--panel-border);
  background: var(--panel-border);
  color: var(--muted);
  cursor: not-allowed;
}

.btn.subtle {
  background: transparent;
  color: var(--primary);
  border-color: var(--panel-border);
}

.btn.subtle:hover:not(:disabled) {
  background: #E8EEF5;
}

.btns {
  display: flex;
  gap: 12px;
  align-items: center;
}

.hint {
  font-size: var(--fs-sec);
  color: var(--muted);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* 答题交互体系 */
.quiz {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.opt {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  padding: 12px 16px;
  border: 1px solid var(--panel-border);
  background: var(--surface);
  border-radius: 6px;
  font-size: var(--fs-body);
  font-weight: 500;
  color: var(--text);
  cursor: pointer;
  text-align: left;
}

.opt:hover:not(:disabled) {
  border-color: var(--primary);
  background: #F8FAFC;
}

.opt:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 1px;
}

.opt.selected {
  border-color: var(--primary);
  background: #EAEFF6;
  font-weight: 600;
}

.opt.correct {
  border-color: var(--primary);
  background: #E5EFF9;
}

.opt.incorrect {
  border-color: var(--accent);
  background: #FDF2F0;
}

.opt:disabled {
  cursor: default;
}

.fb {
  padding: 12px 16px;
  font-size: var(--fs-sec);
  line-height: 1.45;
  border-radius: 6px;
  background: #E8EDF4;
  color: var(--text);
  border-left: 4px solid var(--primary);
}

.fb.accent {
  background: #FDF1EF;
  border-left-color: var(--accent);
}

/* 画布与媒体定位 */
.cvbox {
  position: relative;
  border-radius: 6px;
  overflow: hidden;
  background: #FFFFFF;
  border: 1px solid var(--panel-border);
}

svg .bar, svg .cell, svg .box {
  width: auto;
  height: auto;
}
